# ==============================================================================# 061_DATABASE_SCHEMA.py# IOTEC MISSION CONTROL# DATABASE SCHEMA# ==============================================================================from pathlib import Pathimport sqlite3DB = Path("mission_control.db")class DatabaseSchema:    def __init__(self):        self.conn = sqlite3.connect(DB, timeout=30)        self.conn.execute("PRAGMA journal_mode=WAL")        self.conn.execute("PRAGMA synchronous=NORMAL")        self.conn.execute("PRAGMA busy_timeout=30000")        self.conn.execute("PRAGMA foreign_keys=ON")        self.cur = self.conn.cursor()    # ----------------------------------------------------------------------    def create_missions(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS missions(            id INTEGER PRIMARY KEY AUTOINCREMENT,            mission_name TEXT UNIQUE,            description TEXT,            status TEXT,            priority INTEGER,            created_at TEXT,            updated_at TEXT        )        """)    # ----------------------------------------------------------------------    def create_execution_logs(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS execution_logs(            id INTEGER PRIMARY KEY AUTOINCREMENT,            module TEXT,            status TEXT,            started_at TEXT,            finished_at TEXT,            duration REAL,            message TEXT        )        """)    # ----------------------------------------------------------------------    def create_modules(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS modules(            id INTEGER PRIMARY KEY AUTOINCREMENT,            module_name TEXT UNIQUE,            category TEXT,            version TEXT,            enabled INTEGER DEFAULT 1,            path TEXT,            created_at TEXT        )        """)    # ----------------------------------------------------------------------    def create_events(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS events(            id INTEGER PRIMARY KEY AUTOINCREMENT,            event_name TEXT,            source TEXT,            payload TEXT,            created_at TEXT        )        """)    # ----------------------------------------------------------------------    def create_scheduler(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS scheduler(            id INTEGER PRIMARY KEY AUTOINCREMENT,            task_name TEXT,            interval_seconds INTEGER,            enabled INTEGER DEFAULT 1,            last_execution TEXT,            next_execution TEXT        )        """)    # ----------------------------------------------------------------------    def create_configuration(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS configuration(            key TEXT PRIMARY KEY,            value TEXT        )        """)    # ----------------------------------------------------------------------    def create_runtime(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS runtime(            id INTEGER PRIMARY KEY AUTOINCREMENT,            cpu REAL,            ram REAL,            disk REAL,            created_at TEXT        )        """)    # ----------------------------------------------------------------------    def install(self):        self.create_missions()        self.create_execution_logs()        self.create_modules()        self.create_events()        self.create_scheduler()        self.create_configuration()        self.create_runtime()        self.conn.commit()    # ----------------------------------------------------------------------    def show_tables(self):        self.cur.execute("""        SELECT name        FROM sqlite_master        WHERE type='table'        ORDER BY name        """)        return [x[0] for x in self.cur.fetchall()]# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    schema = DatabaseSchema()    schema.install()    print("=" * 70)    print("MISSION CONTROL DATABASE")    print("=" * 70)    for table in schema.show_tables():        print("[OK]", table)    print("=" * 70)